starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "subnet_ids" {
  description = "Input variable subnet_ids."
  type        = list(string)
}

variable "security_group_ids" {
  description = "Input variable security_group_ids."
  type        = list(string)
}

variable "environment" {
  description = "Input variable environment."
  type        = string
  default     = "dev"
}

variable "project_name" {
  description = "Input variable project_name."
  type        = string
  default     = "terraform-practice"
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_lb" "this" {
  # TODO - Complete the aws_lb resource.
  # Add the arguments and nested blocks required for aws_lb.
}

starter.outputs.tf:
output "lb_arn" {
  value = aws_lb.this.arn
}

output "lb_dns_name" {
  value = aws_lb.this.arn
}
